// Generates src/api/generated/schema.ts from the OpenAPI contract.
// `--check` fails (exit 1) instead of writing when the committed file is stale, for CI.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import { format, resolveConfig } from "prettier";

const contract = new URL("../../../contracts/openapi/materialflow-erp-v1.yaml", import.meta.url);
const target = fileURLToPath(new URL("../src/api/generated/schema.ts", import.meta.url));
const banner =
  "// Generated by `npm run generate:api` from contracts/openapi/materialflow-erp-v1.yaml. Do not edit.\n";

const source = banner + astToString(await openapiTS(contract, { enumValues: true }));
const generated = await format(source, { ...(await resolveConfig(target)), filepath: target });

if (process.argv.includes("--check")) {
  const committed = await readFile(target, "utf8").catch(() => "");
  if (committed !== generated) {
    console.error(
      "src/api/generated/schema.ts is out of date. Run `npm run generate:api` and commit the result.",
    );
    process.exit(1);
  }
  console.log("Generated API client types are up to date.");
} else {
  await writeFile(target, generated);
  console.log(`Wrote ${target}`);
}
